mapper.select:
select * from (select b.ftrid,c.ftrname,c.FTRVALUESTRUCT,c.VALUEEXETYPE,c.type1,c.type2,b.serdate,
b.yvalue, b.keyvalue,b.data,ftrtype2 from ( SELECT * FROM (${sql}
and ${Selectcriteria}
and ${conditionext}
and ${Inputcolumn} = #{Inputvalue}
AND TO_CHAR(${dateperiod},'yyyy-MM-dd') > = #{stDate}
AND TO_CHAR(${dateperiod},'yyyy-MM-dd') <= #{edDate}
order by ${seccode} asc
order by ${desccode} desc
) where 1=1 ) b left join ( select type1,type2,ftrid,EFF_STATUS1 effstatus1,ftrname,FTRVALUESTRUCT,VALUEEXETYPE, EFFSTATUS,REMARK,ftrtype2 from ( select is_visible, b.TIPS_VALUE TIPS_VALUE1, c.TIPS_VALUE TIPS_VALUE2, (select item_value from sys_datadict_list where dict_code = 'FTR_RSK_TYPE' and item_code = b.TIPS_VALUE) type1, (select item_value from sys_datadict_list where dict_code = ( 'FTR_RSK_TYPE'||'_'||b.TIPS_VALUE) and item_code = c.TIPS_VALUE) type2, d.TIPS_VALUE ftrtype2, a.ftr_id ftrid, a.ftr_name ftrname, (select item_value from sys_datadict_list where dict_code = 'VALUE_STRUCT' and item_code = a.FTR_VALUE_STRUCT) FTRVALUESTRUCT, FTR_VALUE_STRUCT FTR_VALUE_STRUCT1, (select item_value from sys_datadict_list where dict_code = 'VALUE_EXE_TYPE' and item_code = a.VALUE_EXE_TYPE) VALUEEXETYPE, (select item_value from sys_datadict_list where dict_code = 'FTR_STATUS' and item_code = a.EFF_STATUS) EFFSTATUS, EFF_STATUS EFF_STATUS1, a.REMARK from STT_FACTOR a left join STT_FACTOR_TIPS b on a.ftr_id= b.FTR_ID and b.dict_code='FTR_RSK_TYPE' left join STT_FACTOR_TIPS c on a.ftr_id= c.FTR_ID and c.dict_code like 'FTR_RSK_TYPE\_%' escape '\' left join STT_FACTOR_TIPS d on a.ftr_id= d.FTR_ID and d.dict_code like 'FTR_RSK_TYPE2' ) where is_visible='E'
and TIPS_VALUE1 =#{type1}
and TIPS_VALUE2 =#{type2}
and ftrtype2 =#{mrkFtrType2}
and ftrid =#{twoClass}
and FTR_VALUE_STRUCT1 =#{FTRVALUESTRUCT}
and EFF_STATUS1 =#{FTRSTATUS}
) c on b.ftrid=c.ftrid where 1=1) where ftrname is not null order by serdate desc,keyvalue asc


select min(START_DATE) sdate,max(END_DATE) edate
from (select STT_SCENE_FACTOR.FTR_ID,
STT_SCENE.START_DATE,
STT_SCENE.END_DATE
from STT_SCENE_FACTOR
left join STT_SCENE
on STT_SCENE_FACTOR.SCENE_ID = STT_SCENE.SCENE_ID
where 1=1

    and STT_SCENE_FACTOR.FTR_ID = =#{twoClass}

)
